import { describe, it, expect } from "vitest";
import { render, screen } from "@testing-library/react";
import { GapCard } from "@/components/gaps/gap-card";
import type { ResearchGap } from "@/api/types";

const sampleGap: ResearchGap = {
  id: 1,
  title: "Lack of cross-lingual transfer methods",
  description: "No methods exist for transferring knowledge between typologically distant languages.",
  gap_type: "methodological",
  confidence: 0.75,
  potential_impact: "High",
};

describe("GapCard", () => {
  it("renders gap title, description, and type badge", () => {
    render(<GapCard gap={sampleGap} />);
    expect(screen.getByText("Lack of cross-lingual transfer methods")).toBeInTheDocument();
    expect(screen.getByText(/No methods exist/)).toBeInTheDocument();
    expect(screen.getByText("methodological")).toBeInTheDocument();
  });

  it("shows confidence percentage", () => {
    render(<GapCard gap={sampleGap} />);
    expect(screen.getByText("75%")).toBeInTheDocument();
  });

  it("renders confidence bar with correct width", () => {
    const { container } = render(<GapCard gap={sampleGap} />);
    const bar = container.querySelector('[style*="width"]');
    expect(bar).toBeTruthy();
    expect(bar?.getAttribute("style")).toContain("75%");
  });
});

import { defineConfig } from "vitest/config";
import react from "@vitejs/plugin-react";
import path from "path";

export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: {
      "@": path.resolve(__dirname, "./src"),
    },
  },
  test: {
    globals: true,
    environment: "jsdom",
    setupFiles: ["./src/test/setup.ts"],
    include: ["src/**/*.test.{ts,tsx}"],
  },
});

import { useQuery } from "@tanstack/react-query";
import { lazy, Suspense } from "react";
import { listRuns } from "@/api/pipeline";
import { getSystemStatus } from "@/api/status";
import { listIdeas } from "@/api/ideas";
import { RunCard } from "@/components/pipeline/run-card";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { useNavigate } from "react-router-dom";
import { Activity, Lightbulb, FlaskConical, Server } from "lucide-react";

const ScoreDistributionChart = lazy(() =>
  import("@/components/charts/score-distribution").then((m) => ({ default: m.ScoreDistributionChart })),
);
const DomainBreakdownChart = lazy(() =>
  import("@/components/charts/domain-breakdown").then((m) => ({ default: m.DomainBreakdownChart })),
);
const RunStatusChart = lazy(() =>
  import("@/components/charts/run-status-chart").then((m) => ({ default: m.RunStatusChart })),
);

export default function Dashboard() {
  const navigate = useNavigate();

  const { data: status, isLoading: statusLoading } = useQuery({
    queryKey: ["status"],
    queryFn: getSystemStatus,
  });

  const { data: runsData, isLoading: runsLoading } = useQuery({
    queryKey: ["runs", { limit: 5 }],
    queryFn: () => listRuns({ limit: 5 }),
  });

  const { data: ideasData, isLoading: ideasLoading } = useQuery({
    queryKey: ["ideas", { limit: 5 }],
    queryFn: () => listIdeas({ limit: 5 }),
  });

  const { data: chartIdeas } = useQuery({
    queryKey: ["ideas", { limit: 200 }],
    queryFn: () => listIdeas({ limit: 200 }),
  });

  const { data: chartRuns } = useQuery({
    queryKey: ["runs", { limit: 50 }],
    queryFn: () => listRuns({ limit: 50 }),
  });

  const hasChartData =
    (chartIdeas?.ideas.length ?? 0) > 0 || (chartRuns?.runs.length ?? 0) > 0;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Dashboard</h1>
        <p className="text-muted-foreground">Overview of your research pipeline.</p>
      </div>

      <div className="grid gap-4 md:grid-cols-3">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">Total Runs</CardTitle>
            <Activity className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            {runsLoading ? (
              <Skeleton className="h-8 w-16" />
            ) : (
              <span className="text-2xl font-bold">{runsData?.total ?? 0}</span>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">Total Ideas</CardTitle>
            <Lightbulb className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            {ideasLoading ? (
              <Skeleton className="h-8 w-16" />
            ) : (
              <span className="text-2xl font-bold">{ideasData?.total ?? 0}</span>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">System</CardTitle>
            <Server className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            {statusLoading ? (
              <Skeleton className="h-8 w-24" />
            ) : (
              <div>
                <span className="text-2xl font-bold">{status?.app_name ?? "—"}</span>
                <p className="text-xs text-muted-foreground">v{status?.version ?? "—"}</p>
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {hasChartData && (
        <Suspense fallback={<Skeleton className="h-64 w-full" />}>
          <div className="space-y-4">
            <h2 className="text-lg font-semibold">Analytics</h2>
            <div className="grid gap-4 md:grid-cols-2">
              <Card>
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Score Distribution</CardTitle>
                </CardHeader>
                <CardContent>
                  <ScoreDistributionChart ideas={chartIdeas?.ideas ?? []} />
                </CardContent>
              </Card>
              <Card>
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Run Status</CardTitle>
                </CardHeader>
                <CardContent>
                  <RunStatusChart runs={chartRuns?.runs ?? []} />
                </CardContent>
              </Card>
            </div>
            <Card>
              <CardHeader>
                <CardTitle className="text-sm font-medium">Ideas by Domain</CardTitle>
              </CardHeader>
              <CardContent>
                <DomainBreakdownChart ideas={chartIdeas?.ideas ?? []} />
              </CardContent>
            </Card>
          </div>
        </Suspense>
      )}

      <div className="grid gap-6 md:grid-cols-2">
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-semibold">Recent Runs</h2>
            <button
              onClick={() => navigate("/pipeline/new")}
              className="text-sm text-primary hover:underline"
            >
              New run
            </button>
          </div>
          {runsLoading ? (
            <div className="space-y-2">
              {Array.from({ length: 3 }).map((_, i) => (
                <Skeleton key={i} className="h-16 w-full" />
              ))}
            </div>
          ) : runsData?.runs.length ? (
            runsData.runs.map((run) => <RunCard key={run.id} run={run} />)
          ) : (
            <Card>
              <CardContent className="p-8 text-center text-muted-foreground">
                <FlaskConical className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No runs yet. Start your first pipeline!</p>
              </CardContent>
            </Card>
          )}
        </div>

        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-semibold">Recent Ideas</h2>
            <button
              onClick={() => navigate("/ideas")}
              className="text-sm text-primary hover:underline"
            >
              View all
            </button>
          </div>
          {ideasLoading ? (
            <div className="space-y-2">
              {Array.from({ length: 3 }).map((_, i) => (
                <Skeleton key={i} className="h-16 w-full" />
              ))}
            </div>
          ) : ideasData?.ideas.length ? (
            ideasData.ideas.map((idea) => (
              <Card
                key={idea.id}
                className="cursor-pointer hover:bg-accent/50 transition-colors"
                onClick={() => navigate(`/ideas/${idea.id}`)}
              >
                <CardContent className="p-4">
                  <p className="text-sm font-medium line-clamp-1">{idea.title}</p>
                  <p className="text-xs text-muted-foreground">{idea.domain}</p>
                </CardContent>
              </Card>
            ))
          ) : (
            <Card>
              <CardContent className="p-8 text-center text-muted-foreground">
                <Lightbulb className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No ideas generated yet.</p>
              </CardContent>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}

import { useState } from "react";
import { RunConfigForm } from "@/components/pipeline/run-config-form";
import { AutonomousForm } from "@/components/pipeline/autonomous-form";
import { StageProgress } from "@/components/pipeline/stage-progress";
import { usePipelineProgress } from "@/hooks/usePipelineProgress";
import { triggerRun } from "@/api/pipeline";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import type { PipelineRunRequest } from "@/api/types";
import { CheckCircle2 } from "lucide-react";

export default function PipelineNew() {
  const [runId, setRunId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { stages, isComplete, isConnected } = usePipelineProgress(runId);

  async function handleStart(config: PipelineRunRequest) {
    setIsLoading(true);
    setError(null);
    try {
      const res = await triggerRun(config);
      setRunId(res.run_id);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to start pipeline");
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Pipeline</h1>
        <p className="text-muted-foreground">Configure and launch a research pipeline.</p>
      </div>

      {!runId && (
        <Tabs defaultValue="single">
          <TabsList>
            <TabsTrigger value="single">Single Run</TabsTrigger>
            <TabsTrigger value="autonomous">Autonomous Cycle</TabsTrigger>
          </TabsList>
          <TabsContent value="single">
            <RunConfigForm onSubmit={handleStart} isLoading={isLoading} />
          </TabsContent>
          <TabsContent value="autonomous">
            <AutonomousForm onCycleStarted={setRunId} />
          </TabsContent>
        </Tabs>
      )}

      {error && (
        <Card className="border-destructive">
          <CardContent className="p-4 text-sm text-destructive">{error}</CardContent>
        </Card>
      )}

      {runId && (
        <Card>
          <CardHeader>
            <div className="flex items-center justify-between">
              <CardTitle className="text-lg">Pipeline Progress</CardTitle>
              <div className="flex items-center gap-2">
                <Badge variant="outline">Run #{runId}</Badge>
                {isComplete ? (
                  <Badge className="bg-green-100 text-green-800">Complete</Badge>
                ) : isConnected ? (
                  <Badge className="bg-blue-100 text-blue-800">Live</Badge>
                ) : (
                  <Badge variant="secondary">Connecting...</Badge>
                )}
              </div>
            </div>
          </CardHeader>
          <CardContent>
            <StageProgress stages={stages} currentStage={null} />
          </CardContent>

          {isComplete && (
            <CardContent className="border-t pt-4">
              <div className="flex items-center gap-2 text-green-700">
                <CheckCircle2 className="h-5 w-5" />
                <span className="font-medium">Pipeline completed successfully</span>
              </div>
            </CardContent>
          )}
        </Card>
      )}
    </div>
  );
}

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { listIdeas } from "@/api/ideas";
import { IdeaCard } from "@/components/ideas/idea-card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { useNavigate } from "react-router-dom";
import { Search, ChevronLeft, ChevronRight } from "lucide-react";

export default function IdeasBrowser() {
  const navigate = useNavigate();
  const [domainFilter, setDomainFilter] = useState("");
  const [page, setPage] = useState(0);
  const limit = 20;

  const { data, isLoading } = useQuery({
    queryKey: ["ideas", { domain: domainFilter, limit, offset: page * limit }],
    queryFn: () =>
      listIdeas({
        domain: domainFilter || undefined,
        limit,
        offset: page * limit,
      }),
  });

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Research Ideas</h1>
        <p className="text-muted-foreground">
          Browse generated ideas with novelty and feasibility scores.
        </p>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        <Input
          placeholder="Filter by domain..."
          value={domainFilter}
          onChange={(e) => {
            setDomainFilter(e.target.value);
            setPage(0);
          }}
          className="pl-9"
        />
      </div>

      {isLoading ? (
        <div className="grid gap-3 md:grid-cols-2">
          {Array.from({ length: 6 }).map((_, i) => (
            <Skeleton key={i} className="h-28 w-full" />
          ))}
        </div>
      ) : data?.ideas.length ? (
        <>
          <p className="text-sm text-muted-foreground">
            {data.total} idea{data.total !== 1 ? "s" : ""} found
          </p>
          <div className="grid gap-3 md:grid-cols-2">
            {data.ideas.map((idea) => (
              <IdeaCard
                key={idea.id}
                idea={idea}
                onClick={() => navigate(`/ideas/${idea.id}`)}
              />
            ))}
          </div>
          {data.total > limit && (
            <div className="flex items-center justify-between pt-2">
              <Button
                variant="outline"
                size="sm"
                disabled={page === 0}
                onClick={() => setPage((p) => p - 1)}
              >
                <ChevronLeft className="mr-1 h-4 w-4" />
                Previous
              </Button>
              <span className="text-sm text-muted-foreground">
                Page {page + 1} of {Math.ceil(data.total / limit)}
              </span>
              <Button
                variant="outline"
                size="sm"
                disabled={(page + 1) * limit >= data.total}
                onClick={() => setPage((p) => p + 1)}
              >
                Next
                <ChevronRight className="ml-1 h-4 w-4" />
              </Button>
            </div>
          )}
        </>
      ) : (
        <div className="text-center py-12 text-muted-foreground">
          <p>No ideas found{domainFilter ? ` for "${domainFilter}"` : ""}.</p>
        </div>
      )}
    </div>
  );
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { getIdea, refineIdea } from "@/api/ideas";
import { ScoreBadge } from "@/components/ideas/score-badge";
import { ExportButton } from "@/components/ideas/export-button";
import { FeedbackForm } from "@/components/ideas/feedback-form";
import { NoveltyReportView } from "@/components/ideas/novelty-report-view";
import { FeasibilityReportView } from "@/components/ideas/feasibility-report-view";
import { MarkdownRenderer } from "@/components/markdown/markdown-renderer";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Separator } from "@/components/ui/separator";
import { Skeleton } from "@/components/ui/skeleton";
import { Button } from "@/components/ui/button";
import { useParams, useNavigate } from "react-router-dom";
import { ArrowLeft, RefreshCw, Loader2 } from "lucide-react";
import { toast } from "sonner";

export default function IdeaDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const ideaId = Number(id);

  const { data, isLoading } = useQuery({
    queryKey: ["idea", ideaId],
    queryFn: () => getIdea(ideaId),
    enabled: !isNaN(ideaId),
  });

  const refineMutation = useMutation({
    mutationFn: () => refineIdea(ideaId),
    onSuccess: () => {
      toast.success("Idea refined — scores updated");
      queryClient.invalidateQueries({ queryKey: ["idea", ideaId] });
    },
    onError: (err) => {
      toast.error(err.message || "Refinement failed");
    },
  });

  if (isLoading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-8 w-32" />
        <Skeleton className="h-10 w-3/4" />
        <Skeleton className="h-64 w-full" />
      </div>
    );
  }

  if (!data?.idea) {
    return (
      <div className="text-center py-12 text-muted-foreground">
        <p>Idea not found.</p>
      </div>
    );
  }

  const idea = data.idea;

  return (
    <div className="space-y-6">
      <div>
        <Button variant="ghost" size="sm" onClick={() => navigate("/ideas")}>
          <ArrowLeft className="mr-2 h-4 w-4" />
          Back to Ideas
        </Button>
      </div>

      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">{idea.title}</h1>
          <p className="text-muted-foreground mt-1">{idea.domain}</p>
          <div className="flex flex-wrap gap-2 mt-3">
            {idea.novelty_score != null && (
              <ScoreBadge score={idea.novelty_score} scale="novelty" />
            )}
            {idea.feasibility_score != null && (
              <ScoreBadge score={idea.feasibility_score} scale="feasibility" />
            )}
            {idea.overall_score != null && (
              <span className="inline-flex items-center rounded-full bg-primary/10 px-2 py-0.5 text-xs font-semibold text-primary">
                Overall: {idea.overall_score.toFixed(2)}
              </span>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2">
          <ExportButton
            proposalMd={idea.proposal_md}
            proposalLatex={idea.proposal_latex}
            title={idea.title}
          />
          <Button
            variant="outline"
            size="sm"
            onClick={() => refineMutation.mutate()}
            disabled={refineMutation.isPending}
          >
            {refineMutation.isPending ? (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            ) : (
              <RefreshCw className="mr-2 h-4 w-4" />
            )}
            Refine
          </Button>
        </div>
      </div>

      <Separator />

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Problem Statement</CardTitle>
        </CardHeader>
        <CardContent>
          <MarkdownRenderer content={idea.problem_statement} />
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Proposed Method</CardTitle>
        </CardHeader>
        <CardContent>
          <MarkdownRenderer content={idea.proposed_method} />
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Expected Contributions</CardTitle>
        </CardHeader>
        <CardContent>
          <MarkdownRenderer content={idea.expected_contributions} />
        </CardContent>
      </Card>

      {(idea.proposal_md || idea.novelty_report || idea.feasibility_report) && (
        <Tabs defaultValue={idea.proposal_md ? "proposal" : idea.novelty_report ? "novelty" : "feasibility"}>
          <TabsList>
            {idea.proposal_md && <TabsTrigger value="proposal">Proposal</TabsTrigger>}
            {idea.novelty_report && <TabsTrigger value="novelty">Novelty Report</TabsTrigger>}
            {idea.feasibility_report && <TabsTrigger value="feasibility">Feasibility Report</TabsTrigger>}
          </TabsList>
          {idea.proposal_md && (
            <TabsContent value="proposal">
              <Card>
                <CardContent className="pt-6">
                  <MarkdownRenderer content={idea.proposal_md} />
                </CardContent>
              </Card>
            </TabsContent>
          )}
          {idea.novelty_report && (
            <TabsContent value="novelty">
              <Card>
                <CardContent className="pt-6">
                  <NoveltyReportView report={idea.novelty_report} />
                </CardContent>
              </Card>
            </TabsContent>
          )}
          {idea.feasibility_report && (
            <TabsContent value="feasibility">
              <Card>
                <CardContent className="pt-6">
                  <FeasibilityReportView report={idea.feasibility_report} />
                </CardContent>
              </Card>
            </TabsContent>
          )}
        </Tabs>
      )}

      <FeedbackForm ideaId={ideaId} />
    </div>
  );
}

import { useQuery } from "@tanstack/react-query";
import { listGaps } from "@/api/gaps";
import { GapCard } from "@/components/gaps/gap-card";
import { Skeleton } from "@/components/ui/skeleton";
import { GitBranch } from "lucide-react";

export default function GapsExplorer() {
  const { data, isLoading } = useQuery({
    queryKey: ["gaps"],
    queryFn: () => listGaps({ limit: 50 }),
  });

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Research Gaps</h1>
        <p className="text-muted-foreground">
          Identified gaps in the literature, sorted by confidence.
        </p>
      </div>

      {isLoading ? (
        <div className="space-y-3">
          {Array.from({ length: 5 }).map((_, i) => (
            <Skeleton key={i} className="h-24 w-full" />
          ))}
        </div>
      ) : data?.gaps.length ? (
        <>
          <p className="text-sm text-muted-foreground">
            {data.total} gap{data.total !== 1 ? "s" : ""} identified
          </p>
          <div className="space-y-3">
            {data.gaps
              .sort((a, b) => b.confidence - a.confidence)
              .map((gap) => (
                <GapCard key={gap.id} gap={gap} />
              ))}
          </div>
        </>
      ) : (
        <div className="text-center py-12 text-muted-foreground">
          <GitBranch className="h-8 w-8 mx-auto mb-2 opacity-50" />
          <p>No research gaps found. Run a pipeline to discover gaps.</p>
        </div>
      )}
    </div>
  );
}

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { searchKnowledge } from "@/api/knowledge";
import { Input } from "@/components/ui/input";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Search, Database, AlertCircle } from "lucide-react";
import { cn } from "@/lib/utils";

function distanceColor(distance: number): string {
  if (distance < 0.3) return "text-green-600";
  if (distance < 0.6) return "text-amber-600";
  return "text-red-600";
}

function distanceLabel(distance: number): string {
  if (distance < 0.3) return "High";
  if (distance < 0.6) return "Medium";
  return "Low";
}

export default function KnowledgeSearch() {
  const [query, setQuery] = useState("");
  const [submittedQuery, setSubmittedQuery] = useState<string | null>(null);

  const { data, isLoading, isError } = useQuery({
    queryKey: ["knowledge-search", submittedQuery],
    queryFn: () => searchKnowledge(submittedQuery!),
    enabled: !!submittedQuery,
  });

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!query.trim()) return;
    setSubmittedQuery(query.trim());
  }

  const results = data?.results ?? [];

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Knowledge Base</h1>
        <p className="text-muted-foreground">Search the indexed literature and papers.</p>
      </div>

      <form onSubmit={handleSubmit} className="relative">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        <Input
          placeholder="Search papers, methods, findings..."
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          className="pl-9"
        />
      </form>

      {isLoading ? (
        <div className="space-y-3">
          {Array.from({ length: 3 }).map((_, i) => (
            <Skeleton key={i} className="h-24 w-full" />
          ))}
        </div>
      ) : isError ? (
        <div className="text-center py-12 text-destructive">
          <AlertCircle className="h-8 w-8 mx-auto mb-2 opacity-70" />
          <p>Search failed. Please try again.</p>
        </div>
      ) : submittedQuery && results.length === 0 ? (
        <div className="text-center py-12 text-muted-foreground">
          <Database className="h-8 w-8 mx-auto mb-2 opacity-50" />
          <p>No results found for "{submittedQuery}".</p>
        </div>
      ) : results.length > 0 ? (
        <div className="space-y-3">
          <p className="text-sm text-muted-foreground">
            {results.length} result{results.length !== 1 ? "s" : ""} for "{submittedQuery}"
          </p>
          {results.map((result) => (
            <Card key={result.id}>
              <CardContent className="p-4">
                <p className="text-sm whitespace-pre-wrap line-clamp-4">{result.text}</p>
                <div className="flex items-center flex-wrap gap-2 mt-3">
                  {result.metadata.source && (
                    <Badge variant="outline" className="text-xs">
                      {result.metadata.source}
                    </Badge>
                  )}
                  {result.metadata.year && (
                    <Badge variant="outline" className="text-xs">
                      {result.metadata.year}
                    </Badge>
                  )}
                  {result.metadata.authors && (
                    <span className="text-xs text-muted-foreground truncate max-w-[200px]">
                      {result.metadata.authors}
                    </span>
                  )}
                  <span className={cn("text-xs font-medium ml-auto", distanceColor(result.distance))}>
                    Relevance: {distanceLabel(result.distance)} ({result.distance.toFixed(3)})
                  </span>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      ) : null}
    </div>
  );
}

import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from "recharts";
import { getNoveltyLabel, getFeasibilityLabel } from "@/lib/score-utils";
import type { IdeaSummary } from "@/api/types";

interface ScoreDistributionChartProps {
  ideas: IdeaSummary[];
}

const bins = ["Low", "Moderate", "High", "Very High"];

function buildData(ideas: IdeaSummary[]) {
  const noveltyCounts: Record<string, number> = { Low: 0, Moderate: 0, High: 0, "Very High": 0 };
  const feasCounts: Record<string, number> = {
    Difficult: 0,
    Moderate: 0,
    Feasible: 0,
    "Very Feasible": 0,
  };

  for (const idea of ideas) {
    if (idea.novelty_score != null) {
      const label = getNoveltyLabel(idea.novelty_score);
      noveltyCounts[label] = (noveltyCounts[label] ?? 0) + 1;
    }
    if (idea.feasibility_score != null) {
      const label = getFeasibilityLabel(idea.feasibility_score);
      feasCounts[label] = (feasCounts[label] ?? 0) + 1;
    }
  }

  // Map feasibility labels to same bin names for grouped display
  const feasMapping: Record<string, string> = {
    Difficult: "Low",
    Moderate: "Moderate",
    Feasible: "High",
    "Very Feasible": "Very High",
  };

  return bins.map((bin) => ({
    bin,
    Novelty: noveltyCounts[bin] ?? 0,
    Feasibility:
      Object.entries(feasMapping)
        .filter(([, v]) => v === bin)
        .reduce((sum, [k]) => sum + (feasCounts[k] ?? 0), 0),
  }));
}

export function ScoreDistributionChart({ ideas }: ScoreDistributionChartProps) {
  const data = buildData(ideas);

  return (
    <ResponsiveContainer width="100%" height={280}>
      <BarChart data={data} margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
        <XAxis dataKey="bin" tick={{ fontSize: 12 }} />
        <YAxis allowDecimals={false} tick={{ fontSize: 12 }} />
        <Tooltip />
        <Legend />
        <Bar dataKey="Novelty" fill="#3b82f6" radius={[4, 4, 0, 0]} />
        <Bar dataKey="Feasibility" fill="#10b981" radius={[4, 4, 0, 0]} />
      </BarChart>
    </ResponsiveContainer>
  );
}
